/* ------------------------------------------------------------ what the builder writes, in words */

const QTYPE: Record<string, string> = { single_select: "single choice", multi_select: "multiple choice", matrix_single: "rating grid", numeric: "number", long_text: "open text", short_text: "short text", ranking: "ranking", slider: "slider", date: "date" };
const TEMPLATE_STRUCTURE: Record<string, string> = {
  pricing_psm: "Price sensitivity block: the four price questions (too cheap, a bargain, getting expensive, too expensive)",
  price_ladder: "Price ladder block: purchase intent at a starting price, moving up or down the ladder until the highest acceptable price is found",
  sequential_monadic: "One block per concept with the same evaluation questions, shown in a rotated order, followed by a preference question",
  brand_funnel: "Brand funnel block: awareness, consideration, use and preference, each brand carried forward from the stage before",
  ad_test: "Advertisement block: exposure to the creative, then attention, branding, message, likeability and intention",
  kano: "Kano block: for each feature, how you feel with it and how you feel without it",
  iat: "Implicit association block: timed sorting tasks",
  shelf_test: "Shelf block: a simulated shelf with a choice task",
};

function plural(n: number, w: string): string { return `${n} ${w}${n === 1 ? "" : "s"}`; }

/** the structure of the study the method's own builder writes for its worked sample */
export function describeBuild(actions: SurveyAction[]): string[] {
  const out: string[] = [];
  const blocks: { title: string; types: string[] }[] = [];
  const at = (title: string) => { let b = blocks.find((x) => x.title === title); if (!b) { b = { title, types: [] }; blocks.push(b); } return b; };
  for (const a of actions as unknown as Record<string, unknown>[]) {
    if (a.op === "create_block") at(String(a.title));
    else if (a.op === "create_question") at(String(a.block ?? "Questions")).types.push(String(a.type));
  }
  const randomized = (actions as unknown as Record<string, unknown>[]).find((a) => a.op === "create_randomizer");
  const cellBlocks = new Set<string>(Array.isArray(randomized?.blocks) ? (randomized!.blocks as string[]) : []);
  if (cellBlocks.size) {
    const first = blocks.find((b) => cellBlocks.has(b.title));
    const show = Number(randomized!.show ?? 1);
    out.push(`${plural(cellBlocks.size, "block")}, one per concept or condition, each with the same ${plural(first?.types.length ?? 0, "question")}; each respondent is randomly given ${show === 1 ? "one" : show} of them, and the assignment is recorded`);
  }
  for (const b of blocks) {
    if (cellBlocks.has(b.title) || !b.types.length) continue;
    const counts = new Map<string, number>();
    for (const t of b.types) counts.set(QTYPE[t] ?? t.replace(/_/g, " "), (counts.get(QTYPE[t] ?? t.replace(/_/g, " ")) ?? 0) + 1);
    out.push(`${b.title}: ${plural(b.types.length, "question")} (${[...counts].map(([t, n]) => (n > 1 ? `${n} × ${t}` : t)).join(", ")})`);
  }
  for (const a of actions as unknown as Record<string, unknown>[]) {
    if (a.op === "add_method_template") out.push(TEMPLATE_STRUCTURE[String(a.template)] ?? `A ${String(a.template).replace(/_/g, " ")} block`);
    if (a.op === "create_conjoint") {
      const method = String(a.method ?? "cbc");
      const n = Array.isArray(a.attributes) ? a.attributes.length : Array.isArray(a.items) ? a.items.length : 0;
      out.push(method === "acbc" ? `An adaptive conjoint exercise over ${plural(n, "attribute")}: build your own, screening, then a choice tournament` : method === "menu" ? `A menu exercise: respondents build their product from ${plural(n, "priced option")}` : method === "cva" || method === "rating" ? `A rating exercise: complete profiles built from ${plural(n, "attribute")}, rated one at a time` : `A choice exercise: a generated design of choice tasks over ${plural(n, "attribute")}${a.none ? ", each with a 'None of these' option" : ""}, in several versions`);
    }
    if (a.op === "create_maxdiff") out.push(`A MaxDiff exercise: a generated design of best–worst sets over ${plural(Array.isArray(a.items) ? a.items.length : 0, "item")}, each item shown a balanced number of times`);
  }
  return out;
}

const INPUT_KIND: Record<string, string> = { text: "", list: "a list", prices: "a list of prices", attributes: "attributes with their levels", number: "a number" };

export function methodGuide(m: Methodology): MethodGuide | null {
  const w = WRITTEN[m.id];
  if (!w) return null;
  let structure: string[] = [];
  try { structure = describeBuild(m.build(sampleInputsFor(m))); } catch { structure = []; }
  if (m.workflow) structure.push(m.workflow.note);
  const data = [
    ...m.inputs.map((i) => `${i.label}${INPUT_KIND[i.kind] ? ` — ${INPUT_KIND[i.kind]}` : ""}${i.required ? " (required)" : ""}`),
    `Sample: ${m.sample.note}${m.sample.perCell ? " — per group compared" : ""}`,
    `Interview length: ${m.loi}`,
  ];
  return {
    id: m.id, what: w[0], when: `Use it when you need ${m.fit}.`, solves: w[1], data, structure,
    considerations: [...m.tradeoffs.map((x) => x.charAt(0).toUpperCase() + x.slice(1)), ...m.strengths.slice(0, 1).map((x) => `What it does well: ${x}`)],
    analysis: m.analysis.map((x) => x.charAt(0).toUpperCase() + x.slice(1)),
    outputs: w[2].split(" | ").map((x) => x.trim()).filter(Boolean), example: w[3], caution: m.caution ?? null,
  };
}

export const METHOD_GUIDE_IDS: string[] = Object.keys(WRITTEN);
